window.products.push({"id":774766,"name":"Rectangular Dish Mold","category":"homeandappliances","retail price":28.39,"sale price":null,"image":"https://m.media-amazon.com/images/I/51uHPnnIk0L._AC_SL1500_.jpg","description":"Serve up style with the simple dish. The elegant rectangle shape makes it ideal as a serving dish or side plate, or as a convenient catch-all dish on the nightstand. No matter where you decide to use it, the understated style will let your glass art design stand out. Reusable mold is pre-drilled and can be fired many times. Mold must be kiln washed before use. See size perspective of mold with quarter images shown. Measures 6-3/4\" x 4-1/8\" and is 1\" deep.","images":["https://m.media-amazon.com/images/I/51uHPnnIk0L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Delphi Glass","source_asin":"B00HHCTF5A","category_path":"Home & Kitchen"},"sku":"BM-774766","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00HHCTF5A","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00HHCTF5A","price_pending":true,"merchant_ready":false});
