window.products.push({"id":774951,"name":"Amazing Glove Hot Surface Handler","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51TGyMRJgLL._AC_SL1200_.jpg","description":"Our heat resistant oven glove will protect you from painful burns while you work in the kitchen. Hot pans and sizzling skillets can create danger and you do not want to risk touching them with something that may not protect your hands. The glove is made from an outer layer of DuPont Nomex and Kevlar which are actually the same materials used in a firefighter's glove. The two materials combined make the heat resistant oven glove exceptionally heat resistant, withstanding temperatures up to a high 480 degrees Fahrenheit. With the heat resistant oven glove you will be able to hold onto really hot kitchen items for much longer and keep your hands much safer from burns. And it even helps protect your fingers while you are grilling during BBQ season.","images":["https://m.media-amazon.com/images/I/51TGyMRJgLL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Oven Gloves","source_asin":"B0088IAVJG","category_path":"Home & Kitchen"},"sku":"BM-774951","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0088IAVJG","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0088IAVJG","price_pending":true,"merchant_ready":false});
